            var parts = new Stack<string?>();
            foreach (var x in filename.Split('/').Reverse()) parts.Push(x);
            int partCount = parts.Count;
            while (partCount > 0)
            {
                var name = parts.Pop();
                if (name == null) { seen[parts.Pop()!] = path; continue; }
                partCount--;
                if (name.Length == 0 || name == ".") continue;
                if (name == "..") { path = path.Substring(0, path.LastIndexOf('/')); if (path.Length == 0) path = "/"; continue; }
                string newpath = path == "/" ? path + name : path + "/" + name;
                string? target = null;
                bool exists = os_.LExists(newpath);
                if (!exists)
                {
                    if (strict) throw OsErrors.NotFound(newpath);
                    path = newpath;
                    continue;
                }
                if (!os_.IsLink(newpath))
                {
                    if (strict && partCount > 0 && !Directory.Exists(newpath)) throw OsErrors.Errno(20, newpath);
                    path = newpath;
                    continue;
                }
                if (seen.TryGetValue(newpath, out var cached))
                {
                    if (cached != null) { path = cached; continue; }
                    if (strict) throw OsErrors.Errno(40, newpath);
                    path = newpath;
                    continue;
                }
                target = new FileInfo(newpath).LinkTarget!;
                if (target.StartsWith('/')) path = "/";
                seen[newpath] = null;
                parts.Push(newpath);
                parts.Push(null);
                var targetParts = target.Split('/');
                for (int k = targetParts.Length - 1; k >= 0; k--) parts.Push(targetParts[k]);
                partCount += targetParts.Length;
            }
            return path;
        }
