    /// <summary>ntpath's string operations (separators '\' and '/', drives and UNC shares).</summary>
    internal static partial class ntpath
    {
        public const string sep = "\\", altsep = "/", pathsep = ";", curdir = ".", pardir = "..", extsep = ".", devnull = "nul";
