            return (t.Length >= 3 && t[1] == ':' && t[2] == '\\') || t.StartsWith("\\\\");
        }

        public static (string, string, string) splitroot(string p)
        {
            string normp = p.Replace('/', '\\');
            if (normp.StartsWith('\\'))
            {
