                    if (index == -1) return (p, "", "");
                    int index2 = normp.IndexOf('\\', index + 1);
                    if (index2 == -1) return (p, "", "");
                    return (p.Substring(0, index2), p.Substring(index2, 1), p.Substring(index2 + 1));
