            if (prefix.Length == 0 && comps.Count == 0) comps.Add(".");
            return prefix + string.Join("\\", comps);
        }

        public static string abspath(string path)
        {
            try { return normpath(System.IO.Path.GetFullPath(path.Length == 0 ? "." : path)); }
            catch (Exception) { return normpath(isabs(path) ? path : join(Environment.CurrentDirectory, new[] { path })); }
        }

        public static string relpath(string path, string? start = null)
        {
            if (path.Length == 0) throw new ArgumentException("no path specified");
            string startAbs = abspath(normpath(start ?? ".")), pathAbs = abspath(normpath(path));
            var (startDrive, _, startRest) = splitroot(startAbs);
            var (pathDrive, _, pathRest) = splitroot(pathAbs);
            if (normcase(startDrive) != normcase(pathDrive)) throw new ArgumentException($"path is on mount {Builtins.repr(pathDrive)}, start on mount {Builtins.repr(startDrive)}");
            var startList = startRest.Length > 0 ? startRest.Split('\\') : Array.Empty<string>();
            var pathList = pathRest.Length > 0 ? pathRest.Split('\\') : Array.Empty<string>();
            int i = 0;
            while (i < startList.Length && i < pathList.Length && normcase(startList[i]) == normcase(pathList[i])) i++;
            var rel = Enumerable.Repeat("..", startList.Length - i).Concat(pathList.Skip(i)).ToList();
            return rel.Count == 0 ? "." : string.Join("\\", rel);
        }

        public static string commonpath(IList<string> paths, bool bytePaths = false)
        {
