            {
                for (int i = 0; i < source.Length; i++) destination[i] = char.IsAsciiLetterUpper(source[i])
                    ? char.ToLowerInvariant(source[i]) : source[i];
            }) : value.ToLowerInvariant();
            var drivesplits = paths.Select(p => splitroot(Fold(p.Replace('/', '\\')))).ToList();
            var splitPaths = drivesplits.Select(d => d.Item3.Split('\\').Where(c => c.Length > 0 && c != ".").ToList()).ToList();
            if (drivesplits.Select(d => d.Item1).Distinct().Count() != 1) throw new ArgumentException("Paths don't have the same drive");
            var (drive, root, path) = splitroot(paths[0].Replace('/', '\\'));
            if (drivesplits.Select(d => d.Item2).Distinct().Count() != 1)
                throw new ArgumentException(drive.Length > 0 ? "Can't mix absolute and relative paths" : "Can't mix rooted and not-rooted paths");
            var common = path.Split('\\').Where(c => c.Length > 0 && c != ".").ToList();
            var s1 = splitPaths.Aggregate((a, b) => GenericPath.CompareLists(a, b) <= 0 ? a : b);
            var s2 = splitPaths.Aggregate((a, b) => GenericPath.CompareLists(a, b) >= 0 ? a : b);
            int n = s1.Count;
            for (int i = 0; i < s1.Count; i++) if (s1[i] != s2[i]) { n = i; break; }
            return drive + root + string.Join("\\", common.Take(n));
        }

        public static string expanduser(string path)
        {
            if (!path.StartsWith('~')) return path;
            int i = 1;
            while (i < path.Length && !IsSep(path[i])) i++;
            string userhome;
            if (os_.environ.TryGetValue("USERPROFILE", out var up)) userhome = up;
            else if (!os_.environ.TryGetValue("HOMEPATH", out var hp)) return path;
            else userhome = join(os_.environ.TryGetValue("HOMEDRIVE", out var hd) ? hd : "", new[] { hp });
            if (i != 1)
            {
                string target = path.Substring(1, i - 1);
                string? current = os_.environ.TryGetValue("USERNAME", out var un) ? un : null;
                if (target != current)
                {
                    if (current != basename(userhome)) return path;
                    userhome = join(dirname(userhome), new[] { target });
                }
            }
            return userhome + path.Substring(i);
        }

        /// <summary>%name%, $name and ${name} replaced (unknown names stay), no expansion inside '...'.</summary>
        public static string expandvars(string path)
        {
            if (!path.Contains('$') && !path.Contains('%')) return path;
            static bool VarChar(char c) => char.IsAsciiLetterOrDigit(c) || c == '_' || c == '-';
            var res = new StringBuilder();
            int index = 0;
            int pathlen = path.Length;
            while (index < pathlen)
            {
                char c = path[index];
                if (c == '\'')
                {
                    path = path.Substring(index + 1);
                    pathlen = path.Length;
                    int q = path.IndexOf('\'');
                    if (q >= 0) { res.Append(c).Append(path, 0, q + 1); index = q; }
                    else { res.Append(c).Append(path); index = pathlen - 1; }
                }
                else if (c == '%')
                {
                    if (index + 1 < pathlen && path[index + 1] == '%') { res.Append(c); index++; }
                    else
                    {
                        path = path.Substring(index + 1);
                        pathlen = path.Length;
                        int p = path.IndexOf('%');
                        if (p < 0) { res.Append('%').Append(path); index = pathlen - 1; }
                        else
                        {
                            string var = path.Substring(0, p);
                            res.Append(os_.environ.TryGetValue(var, out var v) ? v : "%" + var + "%");
                            index = p;
                        }
                    }
                }
                else if (c == '$')
                {
                    if (index + 1 < pathlen && path[index + 1] == '$') { res.Append(c); index++; }
                    else if (index + 1 < pathlen && path[index + 1] == '{')
                    {
                        path = path.Substring(index + 2);
                        pathlen = path.Length;
                        int b = path.IndexOf('}');
                        if (b < 0) { res.Append("${").Append(path); index = pathlen - 1; }
                        else
                        {
                            string var = path.Substring(0, b);
                            res.Append(os_.environ.TryGetValue(var, out var v) ? v : "${" + var + "}");
                            index = b;
                        }
                    }
                    else
                    {
                        var var = new StringBuilder();
                        index++;
                        while (index < pathlen && VarChar(path[index])) { var.Append(path[index]); index++; }
                        res.Append(os_.environ.TryGetValue(var.ToString(), out var v) ? v : "$" + var);
                        if (index < pathlen) index--;
                    }
                }
                else res.Append(c);
                index++;
            }
            return res.ToString();
        }

        public static string realpath(string path, bool strict = false)
        {
            string full = abspath(path);
            if (strict && !os_.LExists(full)) throw OsErrors.NotFound(path);
            try
            {
                FileSystemInfo fi = Directory.Exists(full) ? new DirectoryInfo(full) : new FileInfo(full);
                if (fi.LinkTarget != null && fi.ResolveLinkTarget(true) is FileSystemInfo t) return normpath(t.FullName);
            }
            catch (IOException) { if (strict) throw; }
            return full;
        }
    }

