namespace Typhon.Runtime
{
    using System;
    using System.Collections.Generic;
    using System.Linq;

    /// <summary>genericpath: what posixpath and ntpath share.</summary>
    internal static class GenericPath
    {
        /// <summary>Python's ordering of lists of str (item by item, ordinal; then the shorter first).</summary>
        public static int CompareLists(List<string> a, List<string> b)
        {
            for (int i = 0; i < Math.Min(a.Count, b.Count); i++) { int c = string.CompareOrdinal(a[i], b[i]); if (c != 0) return c; }
            return a.Count.CompareTo(b.Count);
        }

        public static (string, string) splitext(string p, char sep, char? altsep)
        {
            int sepIndex = p.LastIndexOf(sep);
            if (altsep is char a) sepIndex = Math.Max(sepIndex, p.LastIndexOf(a));
            int dotIndex = p.LastIndexOf('.');
            if (dotIndex > sepIndex)
            {
                // a name of leading dots only ('.bashrc', '..') has no extension
                for (int i = sepIndex + 1; i < dotIndex; i++)
                    if (p[i] != '.') return (p.Substring(0, dotIndex), p.Substring(dotIndex));
            }
            return (p, "");
        }

        public static (PyBytes, PyBytes) splitext(PyBytes p, char sep, char? altsep)
        {
            var (root, extension) = splitext(p.decode("latin-1"), sep, altsep);
            return (PyBytes.Latin1(root), PyBytes.Latin1(extension));
        }

        public static dynamic splitext(object p, char sep, char? altsep) => (object)Typhon.Stdlib.os_.fspath(p) switch
        {
            string text => splitext(text, sep, altsep),
            PyBytes bytes => splitext(bytes, sep, altsep),
            _ => throw new InvalidCastException("expected str, bytes or os.PathLike object"),
        };

        public static string commonprefix(IList<string> m)
        {
            if (m.Count == 0) return "";
            string s1 = m.Min(StringComparer.Ordinal)!, s2 = m.Max(StringComparer.Ordinal)!;
            for (int i = 0; i < s1.Length; i++) if (s1[i] != s2[i]) return s1.Substring(0, i);
            return s1;
        }
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Linq;
    using Typhon.Runtime;
    using PosixPath = Typhon.Stdlib.posixpath;
    using NtPath = Typhon.Stdlib.ntpath;

    internal static partial class os_
    {
        internal static PyModule __path_module__ => PyModule.Of(typeof(path), "os.path");

