        {
            static bool Win => OperatingSystem.IsWindows();
            public static readonly string sep = os_.sep;
            public static readonly string? altsep = os_.altsep;
            public const string extsep = ".", curdir = ".", pardir = "..";
            public static readonly string pathsep = os_.pathsep, defpath = os_.defpath, devnull = os_.devnull;
            public static readonly bool supports_unicode_filenames = OperatingSystem.IsWindows() || OperatingSystem.IsMacOS();
            /// <summary>realpath(path, strict=ALLOW_MISSING): missing parts are allowed, other errors raise.</summary>
            public static readonly object ALLOW_MISSING = new object();

