            public static PyBytes normcase(PyBytes s) => Win ? NtPath.normcase(s) : s;
            public static bool isabs(string s) => Win ? NtPath.isabs(s) : PosixPath.isabs(s);
            /// <summary>join(a, *p): an absolute part starts over; join(d, "") ends in a separator.</summary>
            public static string join(string a, params string[] p) => Win ? NtPath.join(a, p) : PosixPath.join(a, p);
            public static PyBytes join(PyBytes a, params PyBytes[] p) =>
                PyBytes.Latin1(join(a.decode("latin-1"), p.Select(part => part.decode("latin-1")).ToArray()));
            public static dynamic join(object a, params object?[] p)
            {
                object first = os_.fspath(a);
                var parts = p.Select(part => (object)os_.fspath(part)).ToArray();
                if (first is string text && parts.All(part => part is string)) return join(text, parts.Cast<string>().ToArray());
                if (first is PyBytes bytes && parts.All(part => part is PyBytes)) return join(bytes, parts.Cast<PyBytes>().ToArray());
                throw new InvalidCastException("Can't mix strings and bytes in path components");
            }
            public static string __join_paths(object? paths)
            {
                var parts = Builtins.__iter_dyn(paths).Select(part => os_.__path((object?)part)).ToArray();
                if (parts.Length == 0) throw new InvalidCastException("join() missing 1 required positional argument: 'a'");
                return join(parts[0], parts[1..]);
            }
            public static (string, string) split(string p) => Win ? NtPath.split(p) : PosixPath.split(p);
            public static (PyBytes, PyBytes) split(PyBytes p)
            {
                var (head, tail) = split(p.decode("latin-1"));
                return (PyBytes.Latin1(head), PyBytes.Latin1(tail));
            }
            public static (string, string) splitext(string p) => Win ? NtPath.splitext(p) : PosixPath.splitext(p);
            public static (PyBytes, PyBytes) splitext(PyBytes p) => Win ? NtPath.splitext(p) : PosixPath.splitext(p);
            public static dynamic splitext(object p) => Win ? NtPath.splitext(p) : PosixPath.splitext(p);
            public static (string, string) splitdrive(string p) => Win ? NtPath.splitdrive(p) : ("", p);
            public static (PyBytes, PyBytes) splitdrive(PyBytes p)
            {
                if (!Win) return (PyBytes.Empty, p);
                var (drive, tail) = NtPath.splitdrive(p.decode("latin-1"));
                return (PyBytes.Latin1(drive), PyBytes.Latin1(tail));
            }
            public static (string, string, string) splitroot(string p) => Win ? NtPath.splitroot(p) : PosixPath.splitroot(p);
            public static string basename(string p) => Win ? NtPath.basename(p) : PosixPath.basename(p);
            public static PyBytes basename(PyBytes p) => split(p).Item2;
            public static string dirname(string p) => Win ? NtPath.dirname(p) : PosixPath.dirname(p);
            public static PyBytes dirname(PyBytes p) => split(p).Item1;
            public static string normpath(string p) => Win ? NtPath.normpath(p) : PosixPath.normpath(p);
            public static string abspath(string p) => Win ? NtPath.abspath(p) : PosixPath.abspath(p);
            public static PyBytes abspath(PyBytes p)
            {
                if (Win) return os_.fsencode(NtPath.abspath(os_.fsdecode(p)));
                string path = p.decode("latin-1");
                if (!PosixPath.isabs(path))
                    path = PosixPath.join(os_.fsencode(Environment.CurrentDirectory).decode("latin-1"), path);
                return PyBytes.Latin1(PosixPath.normpath(path));
            }
            public static string realpath(string p, object? strict = null) => Win ? NtPath.realpath(p, Builtins.truthy(strict) && strict != ALLOW_MISSING) : PosixPath.realpath(p, Builtins.truthy(strict) && strict != ALLOW_MISSING);
            public static string realpath(string p, bool strict) => Win ? NtPath.realpath(p, strict) : PosixPath.realpath(p, strict);
            /// <summary>relpath(path, start=os.curdir): path relative to start, from their normalized absolute forms.</summary>
            public static string relpath(string p, string? start = null) => Win ? NtPath.relpath(p, start) : PosixPath.relpath(p, start);
            public static string commonpath(IEnumerable<string> paths) => Win ? NtPath.commonpath(paths.ToList()) : PosixPath.commonpath(paths.ToList());
            public static dynamic commonpath(object paths)
            {
                var values = new List<string>();
                bool? bytePaths = null;
                foreach (object? value in Builtins.__iter_dyn(paths))
                {
                    object pathname = os_.fspath(value);
                    bool binary = pathname is PyBytes;
                    if (bytePaths is bool previous && previous != binary)
                        throw new InvalidCastException("Can't mix strings and bytes in path components");
                    bytePaths = binary;
                    values.Add(pathname switch
                    {
                        string text => text,
                        PyBytes bytes => bytes.decode("latin-1"),
                        _ => throw new InvalidCastException("expected a string or bytes path"),
                    });
                }
                string prefix = Win ? NtPath.commonpath(values, bytePaths == true) : PosixPath.commonpath(values);
                return bytePaths == true ? PyBytes.Latin1(prefix) : prefix;
            }
            /// <summary>commonprefix(list): the longest common leading string (character by character; deprecated in 3.15).</summary>
            public static string commonprefix(IEnumerable<string> m) => GenericPath.commonprefix(m.ToList());
            public static string expanduser(string p) => Win ? NtPath.expanduser(p) : PosixPath.expanduser(p);
            public static string expandvars(string p) => Win ? NtPath.expandvars(p) : PosixPath.expandvars(p);

            public static bool exists(string p) => p.Length > 0 && (File.Exists(p) || Directory.Exists(p));
            public static bool exists(long fd) { try { fstat(fd); return true; } catch (IOException) { return false; } }
            /// <summary>lexists(path): exists, or a broken symbolic link.</summary>
            public static bool lexists(string p) => p.Length > 0 && LExists(p);
            public static bool lexists(PyBytes p) => lexists(os_.fsdecode(p));
            public static bool isfile(string p) => File.Exists(p);
            public static bool isdir(string p) => Directory.Exists(p);
            public static bool isdir(PyBytes p) => isdir(os_.fsdecode(p));
            public static bool islink(string p) => IsLink(p);
            public static bool isjunction(string p) => false;
            public static bool isdevdrive(string p) => false;
            public static bool isreserved(string p) => false;
            /// <summary>ismount(path): is the path a mount point (a different device than its parent, or the root)?</summary>
            public static bool ismount(string p)
            {
                if (Win)
                {
                    var (drive, root, rest) = NtPath.splitroot(NtPath.abspath(p));
                    if (drive.Length > 0 && (drive[0] == '\\' || drive[0] == '/')) return rest.Length == 0;
                    return root.Length > 0 && rest.Length == 0;
                }
                stat_result s1, s2;
                try { s1 = lstat(p); } catch (Exception) { return false; }
                if ((s1.st_mode & 0xf000) == 0xa000) return false;
                try { s2 = lstat(join(p, "..")); }
                catch (Exception) { try { s2 = lstat(realpath(join(p, ".."))); } catch (Exception) { return false; } }
                if (s1.__identity != null) return abspath(p) == "/";
                return s1.st_dev != s2.st_dev || s1.st_ino == s2.st_ino;
            }
            public static long getsize(string p) => os_.stat(p).st_size;
            public static double getmtime(string p) => os_.stat(p).st_mtime;
            public static double getatime(string p) => os_.stat(p).st_atime;
            public static double getctime(string p) => os_.stat(p).st_ctime;
            /// <summary>samestat(s1, s2): do two stat results describe the same file (device and inode)?</summary>
            public static bool samestat(stat_result s1, stat_result s2) =>
                s1.__identity != null || s2.__identity != null ? s1.__identity == s2.__identity : s1.st_ino == s2.st_ino && s1.st_dev == s2.st_dev;
            public static bool samefile(string f1, string f2) => samestat(os_.stat(f1), os_.stat(f2));
            public static bool sameopenfile(long fp1, long fp2) => samestat(fstat(fp1), fstat(fp2));
        }
    }
}
